// Build Digest — defensively handles missing node outputs
// Uses try/catch to prevent ExpressionError when upstream nodes fail or race
// Lane: hive-os. Daily OS = Grok Bot + Cursor. This n8n digest is a legacy fallback feed.
// Telegram is optional/legacy (G1 soft). Do not fail the run if Telegram is missing.
// Philanthropy :3002 and OpenClaw :18789 are HOLD — not hard-fail gates.
let missions = [];
let goldenPaths = [];

try {
  const missionsOutput = $('Fetch 24h Missions').all();
  if (missionsOutput && missionsOutput.length > 0) {
    const raw = missionsOutput[0].json;
    missions = Array.isArray(raw) ? raw : (raw.data || raw.missions || raw.items || []);
  }
} catch (e) {
  missions = [];
}

try {
  const gpOutput = $('Fetch Golden Paths').all();
  if (gpOutput && gpOutput.length > 0) {
    const raw = gpOutput[0].json;
    goldenPaths = Array.isArray(raw) ? raw : (raw.data || raw.goldenPaths || raw.paths || raw.items || []);
  }
} catch (e) {
  goldenPaths = [];
}

const now = new Date().toISOString();
const missionsCount = missions.length;
const gpCount = goldenPaths.length;
const correlationId = `digest-${Date.now()}`;

const missionsSection = missionsCount > 0
  ? missions.map((m, i) => `${i + 1}. ${m.title || m.name || 'Untitled'} — ${m.status || 'unknown'}`).join('\n')
  : '(No missions in last 24h or fetch failed)';

const gpSection = gpCount > 0
  ? goldenPaths.map((gp, i) => `${i + 1}. ${gp.name || gp.title || 'Untitled'} — ${gp.status || 'active'}`).join('\n')
  : '(No golden paths returned or fetch failed)';

const digest = [
  `HIVE DAILY OPERATIONAL DIGEST (legacy n8n fallback)`,
  `Lane: hive-os · Daily OS: Grok Bot 17 + Cursor`,
  `Generated: ${now}`,
  ``,
  `MISSIONS (last 24h): ${missionsCount}`,
  missionsSection,
  ``,
  `GOLDEN PATHS: ${gpCount}`,
  gpSection,
  ``,
  `Telegram = optional/legacy. Prefer Scorpion register + Grok Watchdog.`,
  `End of digest.`
].join('\n');

return [{
  json: {
    digest,
    missionsCount,
    goldenPathsCount: gpCount,
    generatedAt: now,
    correlationId,
    lane: 'hive-os',
    registerPayload: {
      correlationId,
      jobType: 'hive.daily_operational_digest',
      goal: 'State-of-hive digest for Grok / Scorpion (n8n is not the daily OS)',
      source: 'hive.daily-operational-digest',
      status: 'done',
      registerTo: 'scorpion',
      summary: `digest missions=${missionsCount} goldenPaths=${gpCount}`,
      metadata: {
        lane: 'hive-os',
        telegramRequired: 'false',
        philanthropyHold: 'true',
        openclawHold: 'true'
      }
    },
    fetchErrors: {
      missions: missions.length === 0 ? 'possible fetch failure or empty' : null,
      goldenPaths: goldenPaths.length === 0 ? 'possible fetch failure or empty' : null
    }
  }
}];

// Telegram is LEGACY / optional (G1 soft). Missing token must NOT fail the digest.
const token = $env.TELEGRAM_BOT_TOKEN;
const chatId = $env.HIVE_TELEGRAM_CHAT_ID;
if (!token || token === '' || token === 'undefined' || token === 'null' || !chatId) {
  return [{
    json: {
      ...$json,
      telegramSkipped: true,
      telegramReady: false,
      telegramHint: 'Telegram hive report is optional. Prefer Scorpion register / Grok. Do not fail. Do not renumber Telegram topics.'
    }
  }];
}
return [{
  json: {
    ...$json,
    telegramSkipped: false,
    telegramReady: true,
    _telegram: { token, chatId, ready: true }
  }
}];
